mapper.select:
WITH targets (target_index, subject_id, principal_type, principal_id) AS ( VALUES
(#{index}, #{recipient.subjectId}, #{recipient.principalType}, #{recipient.principalId})
) SELECT t.target_index, COUNT(d.id) AS unread_count FROM targets t LEFT JOIN notification_delivery d ON d.deleted = 0 AND d.status = #{status} AND ( (t.subject_id IS NOT NULL AND t.principal_type IS NULL AND t.principal_id IS NULL AND d.subject_id = t.subject_id AND d.principal_type IS NULL AND d.principal_id IS NULL) OR (t.principal_type IS NOT NULL AND t.principal_id IS NOT NULL AND d.principal_type = t.principal_type AND d.principal_id = t.principal_id AND (t.subject_id IS NULL AND d.subject_id IS NULL OR t.subject_id IS NOT NULL AND (d.subject_id IS NULL OR d.subject_id = t.subject_id))) ) GROUP BY t.target_index ORDER BY t.target_index
